// WF-LOOP-R3 row C1.5 — the GOLDEN test for the measuring instrument.
// `subjects/facade_brick/layout.json` is generated by
// `scripts/measure-target.mjs --freeze`, so the only thing that can keep it
// honest is running the instrument again over the same target and requiring the
// frozen file to still agree with it. This is the test round 2 did not have, and
// its absence is why six frozen keys spent run 3 gating the author against
// numbers nobody had measured (out/wf-loop/r3/fable-audit.md §2 C1).
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

import { measureTarget, checkLayout, checkKey, tolFor, main, ROOT } from "../scripts/measure-target.mjs";

const LAYOUT_FILE = path.join(ROOT, "subjects/facade_brick/layout.json");
const MEASURED_FILE = path.join(ROOT, "subjects/facade_brick/layout.measured.json");

const measured = (await measureTarget({
  targetFile: path.join(ROOT, "refs/tenement-iso.png"),
  regionsFile: path.join(ROOT, "subjects/facade_brick/regions.json"),
  cameraFile: path.join(ROOT, "subjects/facade_brick/camera.json"),   // V5-8 R1: the subject camera (paths.camera)
})).keys;

const frozen = JSON.parse(fs.readFileSync(LAYOUT_FILE, "utf8"));

test("the face frame is the FRONT plane, not front-plus-side", async () => {
  const { frame } = await measureTarget({
    targetFile: path.join(ROOT, "refs/tenement-iso.png"),
    regionsFile: path.join(ROOT, "subjects/facade_brick/regions.json"),
    cameraFile: path.join(ROOT, "subjects/facade_brick/camera.json"),   // V5-8 R1: the subject camera (paths.camera)
  });
  // r2 read x 503..764 (261 px) — the front PLUS the side return — and every
  // fraction along W inherited the error.
  assert.equal(frame.W, 208, `front face measured ${frame.W} px wide, expected 208`);
  assert.ok(Math.abs(frame.H - 550) <= 2, `wall height ${frame.H}, expected 550 +/- 2`);
  assert.ok(frame.x0 > 545 && frame.x0 < 560, `street-left corner at ${frame.x0}`);
  assert.ok(Math.abs(frame.slope - 0.483) < 0.01, `front-plane slope ${frame.slope}`);
});

test("the measurement reproduces the frozen layout within every key's own tol", () => {
  const rows = checkLayout(frozen, measured);
  const bad = rows.filter((r) => !r.ok);
  assert.deepEqual(bad, [], bad.map((r) => `${r.key}: ${r.text}`).join("\n"));
  assert.ok(rows.length >= 20, `only ${rows.length} keys checked`);
});

// The r3 audit's own numbers (research/WF-LOOP-R3.md, Fable M1). Every key here
// is one the scan reproduces to better than 0.01. The three the scan DISAGREES
// with are pinned separately below, with the reason, so neither set can drift
// unnoticed.
const AUDIT = [
  ["window.w", 0.09],
  ["window.centreX", [0.24, 0.815]],
  ["window.headBelowCoping", 0.035],
  ["window.rowPitch", 0.28],
  ["awning.bottom", 0.16],
  ["awning.top", 0.28],
  ["signbox.h", 0.07],
  ["signbox.top", 0.365],
  ["crown.height", 0.027],
  ["ladder.roof.backFromCorner", 0.18],
  ["sideOverFront", 0.786],
];

for (const [key, expected] of AUDIT) {
  test(`scan reproduces the r3 audit's ${key} within 0.01`, () => {
    const entry = measured[key];
    assert.ok(entry && !entry.unverified, `${key} is missing from the measurement`);
    const got = Array.isArray(expected) ? entry.values : [entry.value];
    const want = Array.isArray(expected) ? expected : [expected];
    assert.equal(got.length, want.length);
    for (let i = 0; i < want.length; i += 1) {
      assert.ok(Math.abs(got[i] - want[i]) <= 0.0101,
        `${key}[${i}] measured ${got[i]}, audit says ${want[i]}`);
    }
  });
}

// The scan RECTIFIES before it divides; the audit took three of its numbers off a
// bounding box. A box around a feature w px wide on a plane of slope m is m*w px
// taller than the feature, so a wide, short feature reads far too tall.
test("the three keys the scan contradicts are the three the audit read off a BOX", () => {
  const contradicted = {
    "window.h": { audit: 0.13, scan: 0.120, delta: 0.010 },      // box 74 px over a 19 px pane
    // box 82 px over an 84 px pane; WF-R3-B item 8: the pane's extent at its tallest (un-clipped) columns, 61 px,
    // not the 44 px median under the awning (0.080, which starved the template's LK_AREA glass)
    "storefront.h": { audit: 0.145, scan: 0.111, delta: 0.034 },
    "door.h": { audit: 0.17, scan: 0.127, delta: 0.043 },
  };
  for (const [key, { audit, scan, delta }] of Object.entries(contradicted)) {
    assert.ok(Math.abs(measured[key].value - scan) < 0.005,
      `${key} measured ${measured[key].value}, this test expects ${scan}`);
    assert.ok(Math.abs(Math.abs(measured[key].value - audit) - delta) < 0.002,
      `${key} is now ${Math.abs(measured[key].value - audit).toFixed(3)} off the audit, not ${delta}`);
    assert.match(measured[key].evidence.scan, /per-COLUMN height/,
      `${key} must say in its evidence that it is not a box height`);
  }
});

test("landing.rowY puts the decks BELOW the window bottoms", () => {
  // audit L4: the target's deck tops sit 0.085 H below the sills; run 3 hung the
  // landings on the sills (rowY 0) because r2 eyeballed the key.
  assert.ok(measured["landing.rowY"].value < 0, "the decks must sit below the sills");
  assert.ok(Math.abs(measured["landing.rowY"].value - (-0.085)) <= 0.02,
    `landing.rowY ${measured["landing.rowY"].value}, audit says -0.085`);
});

test("the roof ladder is measured on the SIDE face", () => {
  assert.equal(measured["ladder.roof.face"].value, "side");
});

test("iron.frontShare reconciles with the audit's 6.2 % of the building boxes", () => {
  assert.match(measured["iron.frontShare"].evidence.px, /6\.2 %/);
  assert.equal(measured["iron.frontShare"].measuredBy, "likeness");
});

test("tolerances are FEATURE-RELATIVE, never a blanket 0.05", () => {
  assert.equal(tolFor(0.09), 0.02);          // small features get the 0.02 floor
  assert.equal(tolFor(0.9), 0.135);
  for (const [key, entry] of Object.entries(frozen)) {
    if (key.startsWith("_") || entry.unverified === true || typeof entry.value === "string") continue;
    assert.ok(Number.isFinite(entry.tol), `${key} has no tol`);
    assert.ok(entry.tol >= 0.02 - 1e-9, `${key} tol ${entry.tol} is under the 0.02 floor`);
    // r2's blanket 0.05 let window.h 0.12 mean anything from 0.07 to 0.17 (Astra B2)
    const base = Array.isArray(entry.values) ? Math.min(...entry.values.map(Math.abs)) : Math.abs(entry.value);
    assert.ok(entry.tol <= tolFor(base) + 1e-9, `${key} tol ${entry.tol} is looser than 0.15 x ${base}`);
  }
});

test("--check FAILS on a tampered copy of the layout", async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "measure-target-"));
  const tampered = path.join(dir, "layout.json");
  const copy = JSON.parse(JSON.stringify(frozen));
  copy["window.w"].value = 0.16;             // the r2 number this whole job exists to retire
  fs.writeFileSync(tampered, JSON.stringify(copy, null, 2));

  const rows = checkLayout(copy, measured);
  const bad = rows.filter((r) => !r.ok);
  assert.equal(bad.length, 1, `expected exactly one disagreement, got ${bad.map((r) => r.key).join(", ")}`);
  assert.equal(bad[0].key, "window.w");

  const code = await main(["--check", "--layout", tampered]);
  assert.equal(code, 1, "--check must exit 1 on a tampered layout");
  fs.rmSync(dir, { recursive: true, force: true });
});

test("--check PASSES against the frozen layout the instrument wrote", async () => {
  assert.equal(await main(["--check"]), 0);
});

test("a frozen key with no evidence is a check failure, not a pass", () => {
  assert.ok(checkKey({ value: 0.09, unit: "W", tol: 0.02 }, undefined),
    "a key no measurement produces must be flagged");
  assert.equal(checkKey({ unverified: true }, { unverified: true, reason: "x" }), null);
  assert.ok(checkKey({ value: 0.15, unit: "W", tol: 0.02 }, { unverified: true, reason: "x" }),
    "a frozen NUMBER against an unresolvable measurement must be flagged");
});

test("layout.measured.json is on disk and carries the same keys as the frozen file", () => {
  const file = JSON.parse(fs.readFileSync(MEASURED_FILE, "utf8"));
  const keysOf = (o) => Object.keys(o).filter((k) => !k.startsWith("_")).sort();
  assert.deepEqual(keysOf(file), keysOf(frozen));
  assert.deepEqual(keysOf(file), Object.keys(measured).sort());
});
